import json, csv, re
from pathlib import Path
from normalize_corrections import normalize as normalize_correction

OUT = Path(__file__).resolve().parent
talks = []
items = []
problems = []
corrections = []

def talk(record, date, speaker, pages, title, summary, kind='talk'):
    talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))

def item(record, pages, kind, title, notes, statement, fate, refs=(), *, reconstruction='', cls='E', status='', literal='correct with missing hypotheses', match='exact', verification='read the result', development='annotated', problem='', worth='', confidence='high', speaker=None, area='Lie theory and representation theory'):
    n=1+sum(x['record']==record for x in items)
    d=dict(id=f'1981-{record}.{n}',record=record,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status=status or 'As of November 2026, this is an established result with the hypotheses specified above; the notebook occurrence is expository.',literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence,area=area)
    if speaker:d['speaker']=speaker
    items.append(d)
    return d['id']

def corr(page,place,reads,should,evidence,applies='both',type='faithful_error'):
    corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=type))

def save():
    talks.sort(key=lambda x:x['record'])
    items.sort(key=lambda x:(x['record'],int(x['id'].split('.')[-1])))
    problems.sort(key=lambda x:x['id'])
    for name,data in [('talks',talks),('items',items),('problems',problems)]:
        (OUT/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    with (OUT/'corrections.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(normalize_correction(row) for row in corrections)

talk(530,'1981-09-14','I. M. Gelfand','P000981-P000982','Heading: on contragredient Lie algebras',r'''Only a dated heading and the title \ru{О контраградиентных алгебрах Ли} survive before the next dated heading, 21 September, on P000981. The catalog range extends into P000982, but those mathematical notes belong to the following meeting. No mathematical claim is assigned to this heading-only record.''','heading')
talk(531,'1981-09-21','S. I. Gelfand','P000981-P000985','Reading list and finite-dimensional Lie theory',r'''The meeting begins with a reading list on highest-weight modules and Kac--Moody algebras. Macdonald's June 1981 Bourbaki lecture can be identified exactly as expos\'e 577, \emph{Affine Lie algebras and modular forms}; Humphreys' contribution is the 1980 LNM 831 chapter, pp.~72--103 \citep{macdonald1981affine,humphreys1980highest}. The intervening exposition, explicitly marked I.~M.~G., reviews roots, the Weyl group, Chevalley--Serre relations, highest weights and characters. A speculative Lorentz/neutrino aside has insufficient mathematical specification. The content ends at Rudakov's heading on P000984, not at the catalog endpoint. Several mistakes are in the notebook itself: the order of the symmetric group, the root/weight lattice distinction and omitted off-diagonal restrictions.''')

item(531,'P000981','definition','Adjoint representation and the Killing form',
 r'''The notes introduce \(\operatorname{ad}x(y)=[x,y]\) and a \ru{Картаново скал. пр-ние}; the displayed trace contains a short stroke between \(\operatorname{ad}x\) and \(\operatorname{ad}y\).''',
 r'''For a finite-dimensional complex semisimple Lie algebra \(\mathfrak g\), the Killing form is \(B(x,y)=\operatorname{tr}(\operatorname{ad}x\circ\operatorname{ad}y)\). It is a nondegenerate invariant symmetric complex bilinear form. It is not a positive-definite Hermitian scalar product on \(\mathfrak g\). Its restriction to a Cartan subalgebra is nondegenerate, allowing the induced bilinear form on \(\mathfrak h^*\).''',
 r'''This is classical background explicitly reviewed in \citet[\S1, p.~259]{macdonald1981affine}; \citet[II.2 and III.5]{serre1987complex} supplies the Cartan--Killing criterion and Cartan restriction. The former was delivered in June 1981, before this meeting.''',
 ['macdonald1981affine','serre1987complex'],reconstruction=r'''Composition is the mathematical emendation. The scan does not warrant silently treating the short stroke as an unambiguous multiplication dot; the ambiguity is logged separately.''',literal='not determinable',speaker='I. M. Gelfand')

item(531,'P000981','remark','Approximate Lorentz representations and a neutrino-mass aside',
 r'''Gelfand mentions infinite-dimensional representations close to the standard Lorentz-group representation, an approximate \ru{смещение}, and a small displacement allegedly giving the neutrino a mass; the attribution near Novikov is uncertain.''',
 r'''No unique mathematical problem is recoverable. To formulate one, one would have to specify the Lorentz group or covering group, a class of representations, a topology or deformation parameter, and a Lorentz-covariant dynamical operator whose mass is being computed. None of these data is supplied.''',
 r'''Searches combining Gelfand, Novikov, Lorentz representations, deformation and neutrino mass did not identify a result with these quantifiers. The juxtaposition with highest-weight theory does not identify a mass-generation mechanism. No later neutrino result is claimed as a solution.''',[],cls='F',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',speaker='I. M. Gelfand',area='Mathematical physics',status='As of November 2026, the historical allusion remains unidentified in this bounded search; this is an identification gap, not evidence that a well-posed problem is open.',reconstruction='No technical reconstruction is imposed on this aside.')

item(531,'P000981-P000982','definition','Cartan roots, root spaces and the real root span',
 r'''A root vector is written \(g_\alpha\), and the equation is displayed in the order \([g_\alpha,h]=\alpha(h)g_\alpha\). The exposition then treats the roots as vectors with a positive scalar product.''',
 r'''Fix a Cartan subalgebra \(\mathfrak h\subset\mathfrak g\). With the usual positive-root convention, \(\mathfrak g_\alpha=\{x:[h,x]=\alpha(h)x\text{ for all }h\in\mathfrak h\}\), \(\alpha\ne0\), and \(\mathfrak g=\mathfrak h\oplus\bigoplus_{\alpha\in\Phi}\mathfrak g_\alpha\). Each root space has dimension one. The real span \(E=\operatorname{span}_{\mathbb R}\Phi\subset\mathfrak h^*\) carries a positive-definite Weyl-invariant form; positivity is a statement on this real space, not on the whole complex dual.''',
 r'''The exact finite-dimensional statement is in \citet[\S1, p.~259]{macdonald1981affine} and \citet[VI.1--2]{serre1987complex}. Changing the order of the bracket changes the root sign and must be propagated consistently.''',
 ['macdonald1981affine','serre1987complex'],reconstruction=r'''The separate symbols \(x_\alpha\) and \(\mathfrak g_\alpha\), and the distinction between \(E\) and \(\mathfrak h^*\), are editorial clarifications. The adopted convention agrees with the subsequent raising-operator and highest-weight formulas.''',literal='correct with missing hypotheses',speaker='I. M. Gelfand')

item(531,'P000982','theorem','Simple roots, positivity and the highest root',
 r'''Every root is an integral combination of simple roots with coefficients of one sign. A highest root is singled out.''',
 r'''For a finite reduced crystallographic root system \(\Phi\), a base \(\Delta=\{\alpha_1,\ldots,\alpha_r\}\) is a real basis such that each \(\alpha\in\Phi\) is \(\sum n_i\alpha_i\), where all \(n_i\) are integers and either all are nonnegative or all are nonpositive. For an irreducible system there is a unique highest positive root in the root order; for a reducible system this assertion is made separately in each irreducible component.''',
 r'''This is already stated in the June 1981 reading-list source, \citet[\S1, p.~259]{macdonald1981affine}; the base axioms and highest-root assertion belong to classical finite root-system theory, cf. \citet[V.8--13]{serre1987complex}.''',
 ['macdonald1981affine','serre1987complex'],reconstruction='Irreducibility, needed for a unique highest root, is supplied. No highest-root assertion is carried over to a general infinite Kac--Moody root system.',speaker='I. M. Gelfand')

item(531,'P000982','construction','Coroots and the dual root system',
 r'''The roots \(2\alpha/(\alpha,\alpha)\) are declared to form a root system corresponding to a dual group.''',
 r'''For a reduced crystallographic root system in a Euclidean space, \(\Phi^\vee=\{\alpha^\vee=2\alpha/(\alpha,\alpha):\alpha\in\Phi\}\) is again a reduced crystallographic root system, with transposed Cartan matrix. Passing from a connected reductive group to a dual group requires exchanging the complete root datum \((X^*,\Phi,X_*,\Phi^\vee)\), including its character and cocharacter lattices. The root system alone determines the dual semisimple Lie algebra but not the isogeny class of a group.''',
 r'''The inverse-root construction predates the meeting; see \citet[V.6]{serre1987complex}. The group-language shorthand is compatible with root-datum duality only after the lattice choice is supplied; the notes do not make that choice.''',
 ['serre1987complex'],reconstruction='The distinction between a dual root system and a dual group with specified root datum is an editorial qualification, not an additional theorem attributed to the speaker.',speaker='I. M. Gelfand')

item(531,'P000982','theorem','Weyl reflections and the examples A2 and sl(n)',
 r'''Reflections in the roots generate a finite group. For \(\mathfrak{sl}(n)\) the notes say the symmetric group is \ru{n-го порядка}. The \(\mathfrak{sl}_3\) sketch has three vectors at \(120^\circ\) whose sum is zero.''',
 r'''The reflection is \(s_\alpha(v)=v-\langle v,\alpha^\vee\rangle\alpha\), and the finite Weyl group of \(\mathfrak{sl}_n\) is \(S_n\), acting by coordinate permutation on \(\sum x_i=0\), of order \(n!\). Its roots are \(e_i-e_j\), \(i\ne j\). In type \(A_2\) there are six roots. Three cyclic roots \(e_1-e_2,e_2-e_3,e_3-e_1\) sum to zero and have pairwise angle \(120^\circ\); they are neither the complete root set nor a simple-root base, which has two members.''',
 r'''The correct statements are classical; see \citet[V.3--4 and VII.6]{serre1987complex}. The sketch can be understood accurately as a three-vector subsystem of the drawing after adjoining their negatives. The scan confirms that the order error is in the notes, not generated by translation.''',
 ['serre1987complex'],literal='false as written',speaker='I. M. Gelfand')

item(531,'P000982-P000983','definition','Finite Cartan matrices and their symmetrization',
 r'''The entries \(a_{ij}=\langle\alpha_j,\alpha_i^\vee\rangle\) are described as nonpositive integers, followed by positive definiteness.''',
 r'''A finite-type Cartan matrix has \(a_{ii}=2\), \(a_{ij}\in\mathbb Z_{\le0}\) for \(i\ne j\), and \(a_{ij}=0\iff a_{ji}=0\). It is symmetrizable: a positive diagonal matrix \(D\) makes \(DA\) symmetric positive definite. Equivalently all principal minors of \(A\) are positive. Unless all simple roots have the same length, \(A\) itself need not be symmetric; for example \(\bigl(\begin{smallmatrix}2&-2\\-1&2\end{smallmatrix}\bigr)\) is a finite-type Cartan matrix.''',
 r'''\citet[\S1, condition (C2), p.~260]{macdonald1981affine} uses the principal-minor formulation. The notebook's wording compresses diagonal normalization and symmetrization, so it must not be read as \(a_{ii}\le0\) or as symmetry of every Cartan matrix.''',
 ['macdonald1981affine'],literal='false as written',speaker='I. M. Gelfand')

item(531,'P000983','theorem','Chevalley–Serre presentation',
 r'''The generators \(e_i,f_i,h_i\) obey the Cartan relations and the iterated-adjoint relations with exponent \(1-a_{ij}\); the off-diagonal restriction is not written.''',
 r'''For a finite-type Cartan matrix \(A\), the corresponding complex semisimple Lie algebra is generated by \(e_i,f_i,h_i\), with \([h_i,h_j]=0\), \([h_i,e_j]=a_{ij}e_j\), \([h_i,f_j]=-a_{ij}f_j\), \([e_i,f_j]=\delta_{ij}h_i\), and \((\operatorname{ad}e_i)^{1-a_{ij}}e_j=(\operatorname{ad}f_i)^{1-a_{ij}}f_j=0\) only for \(i\ne j\). Its positive nilpotent subalgebra is presented by the \(e_i\) and the positive Serre relations alone.''',
 r'''This is Serre's presentation, already part of the 1965 lecture course underlying \citet[VI.4, Theorems 6--7, and Appendix]{serre1987complex}; it is also reviewed in \citet[\S1, (1.2)]{macdonald1981affine}. Inserting \(i=j\) would ask for an exponent \(-1\), so the missing qualification is substantive.''',
 ['serre1987complex','macdonald1981affine'],literal='correct with missing hypotheses',speaker='I. M. Gelfand')

item(531,'P000983','theorem','Weight-space decomposition and the weight lattice',
 r'''Finite-dimensional modules split into common eigenspaces of the Cartan subalgebra. The weights are then said to lie in the lattice generated by roots (or coroots).''',
 r'''For a finite-dimensional module over a complex semisimple Lie algebra, \[V=\bigoplus_{\lambda\in P}V_\lambda,\qquad P=\{\lambda\in\mathfrak h^*: \lambda(h_i)\in\mathbb Z\},\] where \(P\) is the weight lattice and \(h_i\) are simple coroots. The root lattice \(Q=\sum_i\mathbb Z\alpha_i\) is a subgroup of \(P\), usually proper. Weights of one irreducible module lie in one coset of \(Q\). For \(\mathfrak{sl}_2\), the defining representation has weights \(\pm\alpha/2\), which are not in \(Q=\mathbb Z\alpha\).''',
 r'''\citet[\S1, pp.~260--261]{macdonald1981affine} explicitly distinguishes \(Q\subset P\) and places representation weights in \(P\). Thus the notebook's lattice statement is false as written, even though its weight decomposition is correct. It cannot be repaired by replacing roots with coroots: these naturally belong to the dual Cartan space.''',
 ['macdonald1981affine'],literal='false as written',speaker='I. M. Gelfand')

item(531,'P000983','theorem','Root vectors shift weights',
 r'''A root vector sends a vector of weight \(\lambda\) to weight \(\lambda+\alpha\); one occurrence writes \(e_\alpha v_\alpha\) where the accompanying calculation uses \(v_\lambda\).''',
 r'''For every weight module and \(x_\alpha\in\mathfrak g_\alpha\), \(x_\alpha V_\lambda\subset V_{\lambda+\alpha}\). Indeed \(h(x_\alpha v)=[h,x_\alpha]v+x_\alpha hv=(\alpha(h)+\lambda(h))x_\alpha v\). The resulting vector may be zero; the assertion does not guarantee that \(\lambda+\alpha\) occurs as a weight.''',
 r'''This elementary relation is \citet[VII.1, Proposition 1(a)]{serre1987complex}. It fixes the bracket convention adopted earlier in the notebook and supplies a direct internal check on the sign of \(\alpha\).''',
 ['serre1987complex'],reconstruction='The nonzero-vector qualification and uniform weight subscript clarify the calculation; the one-line proof is included to show why the convention matters.',speaker='I. M. Gelfand')

item(531,'P000983','theorem','Classification by dominant integral highest weights',
 r'''A vector annihilated by the positive root operators is a highest-weight vector. Cartan's theorem is paraphrased as uniqueness of a representation determined by its highest weight.''',
 r'''For a fixed positive system in a complex semisimple \(\mathfrak g\), finite-dimensional irreducible modules are classified up to isomorphism by \(P_+=\{\lambda:\lambda(h_i)\in\mathbb Z_{\ge0}\}\). The irreducible \(L(\lambda)\) has a one-dimensional highest-weight space annihilated by \(\mathfrak n_+\). For any \(\lambda\in\mathfrak h^*\) there is a unique irreducible highest-weight module, but it is finite-dimensional exactly for \(\lambda\in P_+\). A reducible module is not determined merely by one highest-weight vector.''',
 r'''The finite-dimensional statement is stated in \citet[\S1, p.~261]{macdonald1981affine}; the universal highest-weight construction and finite-dimensional criterion are \citet[VII.3--4, Theorems 1--3]{serre1987complex}. The qualifications separate this theorem from the much larger category of Verma modules treated in record 533.''',
 ['macdonald1981affine','serre1987complex'],speaker='I. M. Gelfand')

item(531,'P000983-P000984','definition','Formal characters and the Weyl vector',
 r'''The group ring of the weight lattice is introduced using formal exponentials, and \(\rho\) is characterized by \(\rho(h_i)=1\).''',
 r'''In \(\mathbb Z[P]\) use symbols \(e^\lambda\) with \(e^\lambda e^\mu=e^{\lambda+\mu}\). A finite-dimensional weight module has character \(\operatorname{ch}V=\sum_\lambda (\dim V_\lambda)e^\lambda\). For a finite root system \(\rho=\frac12\sum_{\alpha>0}\alpha\) satisfies \(\rho(h_i)=1\). In a Kac--Moody setting the latter equations remain meaningful in a realization, whereas a literal half-sum of all positive roots is generally not a finite vector.''',
 r'''The finite-dimensional definitions are exactly the setup of \citet[\S1, p.~261]{macdonald1981affine}. The last warning matters because the later Verma-module discussion shifts to \(G(A)\); one must not carry an infinite half-sum there without a completion or replacement definition.''',
 ['macdonald1981affine'],literal='correct',speaker='I. M. Gelfand')

item(531,'P000984','theorem','Weyl character formula',
 r'''The surviving, uncancelled formula is the alternating Weyl numerator divided by a product over positive roots. A preceding attempt is crossed out in the source.''',
 r'''For \(\lambda\in P_+\), \[\operatorname{ch}L(\lambda)=\frac{\sum_{w\in W}(-1)^{\ell(w)}e^{w(\lambda+\rho)-\rho}}{\prod_{\alpha\in\Phi_+}(1-e^{-\alpha})}.\] The displayed quotient can be taken in the fraction field of \(\mathbb Z[P]\); the theorem says it equals the finite integral character. Equivalently divide \(\sum_w(-1)^{\ell(w)}e^{w(\lambda+\rho)}\) by the Weyl denominator.''',
 r'''This is the classical Weyl formula, reviewed in \citet[\S1, (1.3)]{macdonald1981affine} and \citet[VII.8]{serre1987complex}. The crossed-out formula is evidence of a correction during note-taking and is not treated as a second asserted theorem.''',
 ['macdonald1981affine','serre1987complex'],literal='correct with missing hypotheses',speaker='I. M. Gelfand')

item(531,'P000984','theorem','Weyl denominator and the Vandermonde model',
 r'''The character formula at the trivial highest weight becomes an alternating-sum/product identity. A Vandermonde determinant is displayed as its elementary model.''',
 r'''For a finite root system, \[\sum_{w\in W}(-1)^{\ell(w)}e^{w\rho}=e^\rho\prod_{\alpha>0}(1-e^{-\alpha}).\] For variables \(x_1,\ldots,x_n\), the column convention \(V_{ij}=x_j^{i-1}\) gives \(\det V=\prod_{i<j}(x_j-x_i)\). Type \(A\) specializes the alternating numerator to a determinant after an appropriate monomial factor is removed.''',
 r'''The denominator identity is \citet[\S1, (1.4)]{macdonald1981affine}. The Vandermonde analogy is exact at the determinant level; the source does not specify an ordered product convention, so no independent sign error is inferred from the order of its two variables.''',
 ['macdonald1981affine'],reconstruction='The indices on the Vandermonde product and the determinant convention are supplied explicitly.',literal='correct',speaker='I. M. Gelfand')

